"""Writes the second-stage verification report from the evidence files, so that every figure in the report is the figure
in the evidence. usage: python3 make_report.py <FINAL-VERIFICATION dir> <extra.json>
extra.json holds the few facts that are not in an evidence file (commit ids, test counts read from the test runs)."""
import sys, json, os
FV, extra = sys.argv[1], json.load(open(sys.argv[2]))
E = os.path.join(FV, 'evidence'); J = lambda *p: json.load(open(os.path.join(E, *p), encoding='utf-8'))
fin, pdfc, third, mut, eng = J('financial', 'financial-audit.json'), J('pdf', 'pdf-checks.json'), J('pdf', 'third-reading.json'), J('pdf', 'mutation-test.json'), J('pdf', 'engine-differences.json')
