m = lambda v, d=1: f'{v:,.{d}f}'
F = []          # findings: (id, title, result, what, evidence, repeat)
def add(i, title, result, what, evidence, repeat): F.append({'id': i, 'finding': title, 'result': result, 'what_was_found': what, 'evidence': evidence, 'how_to_repeat': repeat})

h = fin['headline_21_billion']; od = h['open_data_2027_2030_m']; al = h['open_data_all_years_in_the_dataset_m']
a2 = fin['approved_capital_two_datasets']; gl = a2['green_line']; bu = fin['proposed_capital_by_business_unit']; nc = fin['new_capital_13_05_billion']; pos = fin['positions']; opx = fin['operating']; part = opx['requests_only_partly_in_the_budget']
FA = 'evidence/financial/financial-audit.json'; RUNFIN = 'python3 evidence/tools/fin_audit.py ui/budget-intel/business-cases.json ui/budget-intel/crosswalk.json evidence/financial/open-data-nnnm-9sfh-2026-11-11.json evidence/financial/open-data-fqax-i3nz-2026-11-11.json out.json'

